fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: usize = args[1].parse().unwrap();
    if n == 0 {
        println!("1");
        return;
    }
    let base: u64 = 1_000_000_000;
    let mut a: Vec<u32> = vec![1];
    let mut b: Vec<u32> = vec![1];
    for _ in 1..n {
        let len = std::cmp::max(a.len(), b.len());
        let mut c: Vec<u32> = Vec::with_capacity(len + 1);
        let mut carry: u64 = 0;
        for i in 0..len {
            let av = *a.get(i).unwrap_or(&0) as u64;
            let bv = *b.get(i).unwrap_or(&0) as u64;
            let sum = av + bv + carry;
            c.push((sum % base) as u32);
            carry = sum / base;
        }
        if carry > 0 {
            c.push(carry as u32);
        }
        a = b;
        b = c;
    }
    print!("{}", b[b.len() - 1]);
    for i in (0..b.len() - 1).rev() {
        print!("{:09}", b[i]);
    }
    println!();
}
