cd /app/polyglot && rustc /app/polyglot/main.rs && g++ -x c++ /app/polyglot/main.rs -o /app/polyglot/cmain && perl -MMath::BigInt -e '
my @ns=(0,1,2,3,7,20,92,93,185,186,500,1000,5000);
for my $n (@ns) {
  my ($a,$b)=(Math::BigInt->new(1),Math::BigInt->new(1));
  for (1..$n) { my $c=$a+$b; $a=$b; $b=$c; }
  my $e=$n==0?"1":"$a";
  my $r=`/app/polyglot/main $n`; chomp $r;
  my $c=`/app/polyglot/cmain $n`; chomp $c;
  die "MISMATCH n=$n rust=$r cpp=$c expected=$e\n" unless $r eq $c && $r eq $e;
}
print "all outputs match Perl Math::BigInt\n";
' ; status=$?; rm -f /app/polyglot/main /app/polyglot/cmain /app/polyglot/rmain; exit $status

cat > /tmp/fibcheck.cpp <<'CPP'
#include <iostream>
#include <string>
using namespace std;
string s128(__int128 x) {
    if (x == 0) return "0";
    string s;
    while (x > 0) { s.push_back(char('0' + (int)(x % 10))); x /= 10; }
    return string(s.rbegin(), s.rend());
}
int main() {
    __int128 a = 1, b = 1;
    cout << "0 1\n";
    for (int n = 1; n <= 185; ++n) {
        cout << n << " " << (n == 1 ? s128(b) : s128(b)) << "\n";
        __int128 c = a + b; a = b; b = c;
    }
    return 0;
}
CPP
g++ -std=c++17 /tmp/fibcheck.cpp -o /tmp/fibcheck
cd /app/polyglot && rustc /app/polyglot/main.rs && g++ -x c++ /app/polyglot/main.rs -o /app/polyglot/cmain
/tmp/fibcheck | while read n expected; do
  r=$(/app/polyglot/main "$n") || exit 1
  c=$(/app/polyglot/cmain "$n") || exit 1
  if [ "$r" != "$expected" ] || [ "$c" != "$expected" ]; then
    echo "MISMATCH at n=$n rust=$r cpp=$c expected=$expected"; exit 1
  fi
done
st=$?
if [ $st -eq 0 ]; then echo "all 0..185 match independent __int128 calculation"; fi
rm -f /app/polyglot/main /app/polyglot/cmain /tmp/fibcheck /tmp/fibcheck.cpp
exit $st

